var ENT=[["ADRs", "Architecture decision records as memory."], ["Runbooks", "Operational procedures versioned like code."], ["Storybook", "Isolated component workshops."], ["Inner source", "Open-source practices inside companies."], ["Design patterns", "The Gang of Four catalog of proven object-oriented solutions."], ["npm registry", "The world's largest software registry: millions of reusable packages."], ["PyPI", "Python's package index distributing libraries to every Python install."]];
var TECH=[["Pattern mining", "Extracting repeated solutions into named reusable forms."], ["Template parameterization", "Turning examples into templates with well-named variables."], ["Versioned assets", "Releasing reusable pieces with semver and changelogs."], ["Deprecation paths", "Guiding consumers off old assets without breaking them."], ["Curation", "Reviewing and pruning the library so quality stays high."], ["Discoverability", "Search, tags and examples so assets actually get found."], ["Contribution guides", "Lowering the bar for teams to add their solutions."], ["Usage analytics", "Measuring which assets earn their maintenance cost."], ["Golden paths", "Blessed combinations of assets forming the easy default."], ["Feedback loops", "Issue trackers on assets driving continuous improvement."]];
